from threading import RLock

ELEVO_CREDITOS_INICIAIS_V16813 = 100
ELEVO_CUSTO_PROMPT_V16813 = 10
ELEVO_CUSTO_FERRAMENTA_V16813 = 3
ELEVO_CREDITOS_COLS_V16813 = ["Id", "Email", "Data", "Tipo", "Valor", "Referencia", "Autor"]
